const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const { v4: uuidv4 } = require('uuid');
const path = require('path');
const axios = require('axios');
const fs = require('fs');

const app = express();
const PORT = process.env.PORT || 3000;

// Atomicwork Configuration
const ATOMICWORK_BASE_URL = process.env.ATOMICWORK_URL || 'https://atombanking.atomicwork.com';
const ATOMICWORK_API_KEY = process.env.ATOMICWORK_API_KEY || 'aw_b2d3cda25daa4790b460edd9162616advkwta0';

// Middleware
app.use(cors());
app.use(bodyParser.json());
app.use(express.static('public'));

// Load Atomicwork users if file exists
let atomicworkUsers = [];
try {
  const atomicworkData = fs.readFileSync(path.join(__dirname, 'atomicwork-users.json'), 'utf8');
  const parsed = JSON.parse(atomicworkData);
  atomicworkUsers = parsed.users || parsed || [];
  console.log(`Loaded ${atomicworkUsers.length} Atomicwork users from atomicwork-users.json`);
} catch (error) {
  console.log('No atomicwork-users.json found, using default employees only');
}

