async function handleDocumentGeneration(text, employeeId, intent) {
  // Parse document type and params from text
  let docType, params = {};

  if (intent === 'generate_payslip' || text.toLowerCase().includes('payslip')) {
    docType = 'payslip';
    // Extract month and year
    const monthMatch = text.match(/(january|february|march|april|may|june|july|august|september|october|november|december)/i);
    const yearMatch = text.match(/20\d{2}/);
    params.month = monthMatch ? monthMatch[0].charAt(0).toUpperCase() + monthMatch[0].slice(1).toLowerCase() : new Date().toLocaleString('default', { month: 'long' });
    params.year = yearMatch ? parseInt(yearMatch[0]) : new Date().getFullYear();
  } else if (intent === 'generate_tax' || text.toLowerCase().includes('tax') || text.toLowerCase().includes('ir8a')) {
    docType = 'tax_statement';
    const yearMatch = text.match(/20\d{2}/);
    params.year = yearMatch ? parseInt(yearMatch[0]) : new Date().getFullYear() - 1;
  } else if (intent === 'generate_insurance' || text.toLowerCase().includes('insurance') || text.toLowerCase().includes('medishield')) {
    docType = 'insurance_card';
  } else if (intent === 'generate_letter' || text.toLowerCase().includes('employment letter') || text.toLowerCase().includes('verification')) {
    docType = 'employment_letter';
    if (text.toLowerCase().includes('bank') || text.toLowerCase().includes('loan')) {
      params.purpose = 'Bank Loan';
    } else if (text.toLowerCase().includes('visa')) {
      params.purpose = 'Visa Application';
    } else if (text.toLowerCase().includes('hdb')) {
      params.purpose = 'HDB Application';
    } else {
      params.purpose = 'General';
    }
  }

  // Call document generator
  const documentGenerator = require('./document-generator-sg');
  const employee = findEmployeeById(employeeId);

  if (!employee) {
    return { success: false, message: 'Employee not found' };
  }

  let doc;
  switch (docType) {
    case 'payslip':
      doc = documentGenerator.generatePayslipSG(employee, params.month, params.year);
      break;
    case 'tax_statement':
      doc = documentGenerator.generateTaxStatementSG(employee, params.year);
      break;
    case 'insurance_card':
      doc = documentGenerator.generateInsuranceCardSG(employee);
      break;
    case 'employment_letter':
      doc = documentGenerator.generateEmploymentLetterSG(employee, params.purpose);
      break;
    default:
      return { success: false, message: 'Unknown document type' };
  }

  return {
    success: true,
    message: `${doc.title} generated successfully`,
    data: doc
  };
}

// ==================== BUSINESS LOGIC FUNCTIONS ====================
function processLeaveApplication(details, metadata = {}) {
  const employee = findEmployeeById(details.employeeId);

  if (!employee) {
    return { success: false, message: 'Employee not found' };
  }

  const leaveType = details.type || 'annual';
  const days = details.days || 1;

  // Strict Date Validation
  if (!details.startDate) {
    return {
      success: false,
      message: 'Please specify the start date for your leave (e.g., "from March 1st").'
    };
  }

  // Calculate End Date if missing but days provided
  let endDate = details.endDate;
  if (!endDate && details.startDate && days > 1) {
    endDate = calculateEndDate(details.startDate, days);
  } else if (!endDate) {
    endDate = details.startDate; // Single day leave
  }

  // Check leave balance
  if (employee.leaveBalance[leaveType] < days) {
    return {
      success: false,
      message: `Insufficient ${leaveType} leave balance. Available: ${employee.leaveBalance[leaveType]} days, Requested: ${days} days`
    };
  }

  const employeeName = employee.full_name || `${employee.first_name} ${employee.last_name || ''}`.trim();

  const leaveRequest = {
    id: `LV-${uuidv4().substring(0, 8)}`,
    employeeId: employee.id,
    employeeName: employeeName,
    type: leaveType,
    startDate: details.startDate,
    endDate: endDate,
    days: days,
    status: 'approved', // Auto-approve all requests from NLP webhook as they are pre-verified
    appliedAt: new Date().toISOString(),
    approver: metadata.approver || employee.manager || 'AUTO',
    approvalNotes: metadata.approvalNotes || 'Auto-approved via Atomicwork Webhook',
    approvalComment: metadata.approvalComment || '',
    metadata
  };

  leaveRequests.push(leaveRequest);

  // Deduct leave balance for approved requests
  if (leaveRequest.status === 'approved') {
    employee.leaveBalance[leaveType] -= days;
  }

  return {
    success: true,
    message: `Leave request auto-approved! ${days} day(s) of ${leaveType} leave from ${leaveRequest.startDate} to ${leaveRequest.endDate}`,
    data: leaveRequest,
    updatedBalance: employee.leaveBalance
  };
}

function getLeaveBalance(employeeId) {
  const employee = findEmployeeById(employeeId);

  if (!employee) {
    return { success: false, message: 'Employee not found' };
  }

  const employeeName = employee.full_name || `${employee.first_name} ${employee.last_name || ''}`.trim();

  return {
    success: true,
    message: `Leave balance for ${employeeName}`,
    data: {
      employeeId: employee.id,
      employeeName: employeeName,
      balance: employee.leaveBalance,
      total: employee.leaveBalance.annual + employee.leaveBalance.sick + employee.leaveBalance.personal
    }
  };
}

function markAttendance(employeeId, metadata = {}) {
  const employee = findEmployeeById(employeeId);

  if (!employee) {
    return { success: false, message: 'Employee not found' };
  }

  const today = new Date().toISOString().split('T')[0];
  const existing = attendance.find(a => a.employeeId === employeeId && a.date === today);

  if (existing) {
    return {
      success: false,
      message: 'Attendance already marked for today',
      data: existing
    };
  }

  const employeeName = employee.full_name || `${employee.first_name} ${employee.last_name || ''}`.trim();

  const record = {
    id: `ATT-${uuidv4().substring(0, 8)}`,
    employeeId,
    employeeName: employeeName,
    date: today,
    checkIn: new Date().toISOString(),
    status: 'present',
    metadata
  };

  attendance.push(record);

  return {
    success: true,
    message: `Attendance marked successfully for ${employeeName}`,
    data: record
  };
}

function processReimbursement(details, metadata = {}) {
  const employee = findEmployeeById(details.employeeId);

  if (!employee) {
    return { success: false, message: 'Employee not found' };
  }

  const amount = details.amount || 0;
  const autoApproveThreshold = 500;

  const employeeName = employee.full_name || `${employee.first_name} ${employee.last_name || ''}`.trim();

  const reimbursement = {
    id: `REIMB-${uuidv4().substring(0, 8)}`,
    employeeId: details.employeeId,
    employeeName: employeeName,
    amount: amount,
    category: details.category || 'other',
    description: details.description || `${(details.category || 'other').replace('_', ' ')} expense reimbursement`,
    status: metadata.approvalStatus || (amount <= autoApproveThreshold ? 'approved' : 'pending'),
    submittedAt: new Date().toISOString(),
    approver: metadata.approver || (amount <= autoApproveThreshold ? 'AUTO' : employee.manager),
    approvalNotes: metadata.approvalNotes || '',
    approvalComment: metadata.approvalComment || '',
    metadata
  };

  reimbursements.push(reimbursement);

  return {
    success: true,
    message: reimbursement.status === 'approved'
      ? `Reimbursement auto-approved! $${amount} will be processed in the next payroll cycle.`
      : `Reimbursement submitted for approval. Request ID: ${reimbursement.id}`,
    data: reimbursement
  };
}

function createPurchaseOrder(details, metadata = {}) {
  const po = {
    id: `PO-${uuidv4().substring(0, 8)}`,
    poNumber: `PO-${Date.now()}`,
    vendor: details.vendor || 'Unknown Vendor',
    items: details.items || 'Various items',
    amount: details.amount || 0,
    description: details.description || `PO for ${details.items || 'various items'} from ${details.vendor || 'vendor'}`,
    status: 'pending_approval',
    requestedBy: details.requestedBy,
    createdAt: new Date().toISOString(),
    metadata
  };

  purchaseOrders.push(po);

  return {
    success: true,
    message: `Purchase Order created successfully. PO Number: ${po.poNumber}`,
    data: po
  };
}

function submitInvoice(details, metadata = {}) {
  const invoice = {
    id: `INV-${uuidv4().substring(0, 8)}`,
    invoiceNumber: details.invoiceNumber || `INV-${Date.now()}`,
    vendor: details.vendor || 'Unknown Vendor',
    amount: details.amount || 0,
    description: details.description || `Invoice from ${details.vendor || 'vendor'}`,
    status: 'pending_verification',
    submittedBy: details.submittedBy,
    submittedAt: new Date().toISOString(),
    matchedPO: null,
    metadata
  };

  // Try to match with existing PO
  const matchingPO = purchaseOrders.find(po =>
    po.vendor === invoice.vendor &&
    Math.abs(po.amount - invoice.amount) < 0.01
  );

  if (matchingPO) {
    invoice.matchedPO = matchingPO.poNumber;
    invoice.status = 'matched';
  }

  invoices.push(invoice);

  return {
    success: true,
    message: invoice.matchedPO
      ? `Invoice matched with PO ${invoice.matchedPO} and ready for payment processing.`
      : `Invoice submitted for verification. Invoice Number: ${invoice.invoiceNumber}`,
    data: invoice
  };
}

// ==================== REST API ENDPOINTS ====================

// Employees
app.get('/api/employees', (req, res) => {
  res.json({ success: true, data: employees });
});

app.get('/api/employees/:id', (req, res) => {
  const employee = employees.find(e => e.id == req.params.id || e.employee_id == req.params.id);
  if (!employee) {
    return res.status(404).json({ success: false, message: 'Employee not found' });
  }
  res.json({ success: true, data: employee });
});

// Leave Requests
app.get('/api/leave-requests', (req, res) => {
  res.json({ success: true, data: leaveRequests });
});

app.post('/api/leave-requests', (req, res) => {
  const result = processLeaveApplication(req.body);
  res.json(result);
});

app.patch('/api/leave-requests/:id/approve', (req, res) => {
  const leave = leaveRequests.find(l => l.id === req.params.id);
  if (!leave) {
    return res.status(404).json({ success: false, message: 'Leave request not found' });
  }

  leave.status = 'approved';
  const employee = employees.find(e => e.id === leave.employeeId);
  if (employee) {
    employee.leaveBalance[leave.type] -= leave.days;
  }

  res.json({ success: true, message: 'Leave approved', data: leave });
});

app.get('/api/leave-balance/:employeeId', (req, res) => {
  const result = getLeaveBalance(req.params.employeeId);
  if (!result.success) {
    return res.status(404).json(result);
  }
  res.json(result);
});

// Attendance
app.get('/api/attendance', (req, res) => {
  res.json({ success: true, data: attendance });
});

app.post('/api/attendance', (req, res) => {
  const result = markAttendance(req.body.employeeId);
  res.json(result);
});

// Reimbursements
