// Health check
// Document Generation
const documentGenerator = require('./document-generator');
const documentGeneratorSG = require('./document-generator-sg');

app.post('/api/documents/generate', (req, res) => {
  const { employeeId, type, params, country } = req.body;

  const employee = employees.find(e => e.id == employeeId || e.employee_id == employeeId || e.email == employeeId);
  if (!employee) {
    return res.status(404).json({ success: false, error: 'Employee not found' });
  }

  let doc;
  const isSingapore = country === 'SG' || country === 'Singapore';

  try {
    if (isSingapore) {
      // Singapore documents
      switch (type) {
        case 'tax_statement':
        case 'tax_statement_sg':
          doc = documentGeneratorSG.generateTaxStatementSG(employee, params?.year);
          break;
        case 'payslip':
        case 'payslip_sg':
          doc = documentGeneratorSG.generatePayslipSG(employee, params?.month, params?.year);
          break;
        case 'insurance_card':
        case 'insurance_card_sg':
          doc = documentGeneratorSG.generateInsuranceCardSG(employee);
          break;
        case 'employment_letter':
        case 'employment_letter_sg':
          doc = documentGeneratorSG.generateEmploymentLetterSG(employee, params?.purpose);
          break;
        default:
          return res.status(400).json({ success: false, error: 'Invalid document type' });
      }
    } else {
      // Default (US/India) documents
      switch (type) {
        case 'tax_statement':
          doc = documentGenerator.generateTaxStatement(employee, params?.year);
          break;
        case 'payslip':
          doc = documentGenerator.generatePayslip(employee, params?.month, params?.year);
          break;
        case 'insurance_card':
          doc = documentGenerator.generateInsuranceCard(employee);
          break;
        case 'employment_letter':
          doc = documentGenerator.generateEmploymentLetter(employee, params?.purpose);
          break;
        default:
          return res.status(400).json({ success: false, error: 'Invalid document type' });
      }
    }

    res.json({ success: true, data: doc });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

app.get('/api/documents', (req, res) => {
  const { employeeId } = req.query;

  let docs = [...documentGenerator.generatedDocuments, ...documentGeneratorSG.generatedDocuments];

  if (employeeId) {
    docs = docs.filter(d => d.employeeId == employeeId);
  }

  res.json({ success: true, data: docs });
});

app.get('/api/health', (req, res) => {
  res.json({
    success: true,
    message: 'Sage HR Mock API is running',
    timestamp: new Date().toISOString(),
    stats: {
      employees: employees.length,
      leaveRequests: leaveRequests.length,
      attendance: attendance.length,
      reimbursements: reimbursements.length,
      purchaseOrders: purchaseOrders.length,
      invoices: invoices.length
    }
  });
});

